        return False
    h, w, pts = shape
    _, _, qts = template
    for transform in (
        lambda r, c: (r, c),
        lambda r, c: (h - 1 - r, c),
        lambda r, c: (r, w - 1 - c),
        lambda r, c: (h - 1 - r, w - 1 - c),
    ):
        if pts == frozenset(transform(r, c) for r, c in qts):
            return True
    return False


