def _panels(grid):
    h, w = len(grid), len(grid[0])
    sr = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sc = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]
    rb, cb = [-1] + sr + [h], [-1] + sc + [w]
    rows = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cols = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    return rows, cols


