    out = [row[:] for row in grid]
    bands, panels = _panels(out)
    # Shape maps: (panel-row, panel-col, color) -> local coordinates.
    shapes = {}
    for bi, (r0, r1) in enumerate(bands):
        for pj, (c0, c1) in enumerate(panels):
            colors = {out[r][c] for r in range(r0, r1) for c in range(c0, c1) if out[r][c] != 0}
            for color in colors:
                shapes[bi, pj, color] = frozenset((r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if out[r][c] == color)

    # If a pair of columns is known to hold horizontal mirror partners for a
    # color in one row, complete a lone partner in another row.
    pair_templates = set()
    for bi, (r0, r1) in enumerate(bands):
        for pj in range(len(panels) - 1):
            w = panels[pj][1] - panels[pj][0]
            if panels[pj + 1][1] - panels[pj + 1][0] != w:
                continue
            colors = {key[2] for key in shapes if key[0] == bi and key[1] in (pj, pj+1)}
            for color in colors:
                a = shapes.get((bi, pj, color), frozenset())
                b = shapes.get((bi, pj+1, color), frozenset())
                if a and b and _flip(a, r1-r0, w, horizontal=True) == b:
                    pair_templates.add((pj, color))
    for pj, color in pair_templates:
        w = panels[pj][1] - panels[pj][0]
        for bi, (r0, r1) in enumerate(bands):
            a = shapes.get((bi, pj, color), frozenset())
            b = shapes.get((bi, pj+1, color), frozenset())
            if bool(a) == bool(b):
                continue
            src = a or b
            dstj = pj+1 if a else pj
            reflected = _flip(src, r1-r0, w, horizontal=True)
            dc0 = panels[dstj][0]
            for rr, cc in reflected:
                out[r0+rr][dc0+cc] = color

    # Complete 2x2 reflection orbits when three of the four variants exist.
    for bi in range(len(bands)-1):
        r0, r1 = bands[bi]
        nh = r1-r0
        if bands[bi+1][1]-bands[bi+1][0] != nh:
            continue
        for pj in range(len(panels)-1):
            c0, c1 = panels[pj]
            nw = c1-c0
            if panels[pj+1][1]-panels[pj+1][0] != nw:
                continue
            for color in {key[2] for key in shapes}:
                found = []
                for dr in (0, 1):
                    for dc in (0, 1):
                        s = shapes.get((bi+dr, pj+dc, color), frozenset())
                        if s:
                            found.append((dr, dc, s))
                if len(found) != 3:
                    continue
                for sr, sc, ss in found:
                    base = _flip(ss, nh, nw, vertical=bool(sr), horizontal=bool(sc))
                    expected = {(dr, dc): _flip(base, nh, nw, vertical=bool(dr), horizontal=bool(dc)) for dr in (0,1) for dc in (0,1)}
                    if all(shapes.get((bi+dr, pj+dc, color), frozenset()) in (frozenset(), expected[dr,dc]) for dr in (0,1) for dc in (0,1)) and sum(shapes.get((bi+dr,pj+dc,color),frozenset()) == expected[dr,dc] for dr in (0,1) for dc in (0,1)) == 3:
